SELECT game_id AS "gameId", listener_id AS "listenerId", provider_id AS "providerId", listener_key AS "listenerKey", event_type_id AS "eventTypeId", ability_id AS "abilityId", max_triggers_per_event AS "maxTriggersPerEvent", chain_limit_key AS "chainLimitKey", change_revision AS "changeRevision", updated_at AS "updatedAt" FROM public.provider_listeners WHERE game_id = #{gameId}
AND provider_id = #{providerId}
AND ability_id = #{abilityId}
ORDER BY provider_id, listener_id
